import { strict as assert } from "node:assert";
import { Database } from "bun:sqlite";
import { SQL } from "bun";
import { mkdtempSync, readFileSync } from "node:fs";
import { join } from "node:path";
import { pathToFileURL } from "node:url";
const root="/private/tmp/rm306-singleton-review.I2egyF";
const url=Bun.env.REVIEW_DATABASE_URL;
delete Bun.env.DATABASE_URL; delete Bun.env.SQLITE_PATH;
if(url) {const u=new URL(url); assert.equal(u.hostname,"127.0.0.1");assert.match(u.pathname,/^\/jadpo_auth_test_singleton_[a-z_]+$/);Bun.env.DATABASE_URL=url;}
else Bun.env.SQLITE_PATH=join(mkdtempSync(join(root,"sqlite-native-")),"application.sqlite");
const {persistence}=await import(pathToFileURL(join(root,"generated/persistence.ts")).href);
const binding=JSON.parse(readFileSync(join(root,"generated/binding.json"),"utf8"));
assert.equal(binding.execution_profile,null);assert.equal(binding.runtime_lowering_supported,false);
const db=url?null:new Database(Bun.env.SQLITE_PATH);
const sql=url?new SQL(url,{max:5,prepare:false}):null;
const rows=(s:string,v:any[]=[])=>sql?sql.unsafe(s,v):Promise.resolve(db!.prepare(s).all(...v));
const instant="2026-10-05T08:01:02.003Z", resume="2026-10-06T08:01:02.003Z", interval=900_000;
const profile={executionMs:120_000,leaseMs:90_000}; // Fixture-only; never a public default.
const tick=(b:string,at=instant,ms=interval)=>persistence.transaction((tx:any)=>tx.tick_delivery_schedule(b,ms,at));
const claim=(b:string,at=instant,p=profile)=>persistence.transaction((tx:any)=>tx.claim_delivery_activation(b,at,p));
const stage=(h:any,ids:any,after:any=null)=>persistence.transaction((tx:any)=>tx.stage_delivery_activation_page(h,ids,after));
const finish=(h:any)=>persistence.transaction((tx:any)=>tx.finish_delivery_activation(h));
const state=async(b:string)=>(await rows('SELECT * FROM "__jadpo_delivery_activations_v1" WHERE binding=$1',[b]))[0];
const expire=(b:string)=>rows('UPDATE "__jadpo_delivery_activations_v1" SET lease_until=$1 WHERE binding=$2',["2000-01-01T00:00:00.000Z",b]);
const violations:string[]=[];

// Each fresh native binding is a trusted compiler-host seam, not an authored capability.
const bounded=crypto.randomUUID();await tick(bounded);
for(const ms of [0,-1,1.5,NaN,Infinity,Number.MAX_SAFE_INTEGER+1]) await assert.rejects(tick(bounded,instant,ms),(e:any)=>e.operation==="delivery.activation_profile");
for(const at of ["bad","2026-10-05T08:01:02Z","2026-02-30T08:01:02.003Z","2026-10-05T08:01:02.003+00:00"]) await assert.rejects(tick(bounded,at),(e:any)=>e.operation==="delivery.activation_time");
for(const p of [null,{}, {executionMs:0,leaseMs:1},{executionMs:1,leaseMs:2},{executionMs:1.5,leaseMs:1},{executionMs:Infinity,leaseMs:1},{executionMs:Number.MAX_SAFE_INTEGER,leaseMs:1},{...profile,extra:1}]) await assert.rejects(claim(bounded,instant,p),(e:any)=>e.operation==="delivery.activation_profile");
assert.equal((await state(bounded)).activation_id,null);
await assert.rejects(tick(bounded,instant,interval*2),(e:any)=>e.operation==="delivery.activation_interval");
await assert.rejects(persistence.tick_delivery_schedule(bounded,interval,instant),(e:any)=>e.operation==="delivery.transaction_required");
console.log('PASS exact canonical UTC/positive finite integer profile/interval mismatch/outside-TX negatives preserve pending row');

const work=crypto.randomUUID();await tick(work);const h=await claim(work);
const ids=Array.from({length:500},()=>crypto.randomUUID()), after={opaque:"trusted host cursor"};
for(const bad of [[...ids,crypto.randomUUID()], [ids[0],ids[0]], [""], [4], null]) await assert.rejects(stage(h,bad,after),(e:any)=>e.operation==="delivery.activation_page");
assert.equal((await state(work)).page,null);
await assert.rejects(persistence.transaction(async(tx:any)=>{await tx.stage_delivery_activation_page(h,ids,after);throw new Error("fixture rollback");}));
assert.equal((await state(work)).page,null);
assert.equal(await stage(h,ids,after),true);
const stored=JSON.parse((await state(work)).page);ids[0]="detached mutation";after.opaque="mutated outside";
assert.deepEqual(JSON.parse((await state(work)).page),stored);
await assert.rejects(stage(h,[],null),(e:any)=>e.operation==="delivery.activation_page_staged");
await tick(work,"2026-10-05T08:15:00.000Z");await tick(work,"2026-10-05T08:45:00.000Z");
await expire(work);const recovered=await claim(work,resume);assert.equal(recovered.generation,"2");
assert.equal(recovered.operationTime,resume);assert.equal(recovered.scheduledFor,h.scheduledFor);assert.deepEqual(recovered.page,stored);
assert.equal(await finish(h),false);assert.equal(await stage(h,[]),false);
await assert.rejects(persistence.transaction(async(tx:any)=>{await tx.finish_delivery_activation(recovered);throw new Error("finish rollback");}));
assert.deepEqual(JSON.parse((await state(work)).page),stored);
assert.equal(await finish(recovered),true);
const continuation=await claim(work,resume);assert.deepEqual(continuation.cursor,stored.after);assert.equal(continuation.scheduledFor,h.scheduledFor);
assert.equal(await stage(continuation,[],null),true);assert.equal(await finish(continuation),true);
const followup=await claim(work,resume);assert.equal(followup.scheduledFor,"2026-10-05T08:45:00.000Z");
assert.equal(await stage(followup,[],null),true);assert.equal(await finish(followup),true);assert.equal(await claim(work,resume),null);
console.log('PASS immutable500-ID worklist, rollback, fenced fresh-snapshot resume, continuation before exactly one latest follow-up');

for(const encoded of ['{"intentIds":["duplicate","duplicate"],"after":null}','{"intentIds":[],"after":null,"extra":true}','{malformed']) {
  const b=crypto.randomUUID();await tick(b);const old=await claim(b);await expire(b);
  await rows('UPDATE "__jadpo_delivery_activations_v1" SET page=$1 WHERE binding=$2',[encoded,b]);
  await assert.rejects(claim(b,resume));const s=await state(b);
  assert.equal(String(s.generation),old.generation);assert.equal(s.activation_id,old.activationId);assert.equal(s.page,encoded);
}
const exhausted=crypto.randomUUID();await tick(exhausted);
await rows('UPDATE "__jadpo_delivery_activations_v1" SET generation=9223372036854775807 WHERE binding=$1',[exhausted]);
await assert.rejects(claim(exhausted),(e:any)=>e.operation==="delivery.activation_generation");
console.log('PASS malformed/duplicate/extra persisted page refuses atomically; exhausted fencing generation refuses');

const corrupt=crypto.randomUUID();await tick(corrupt);const old=await claim(corrupt);await expire(corrupt);
// Native storage-corruption challenge, not forgery of an authored capability.
await rows('UPDATE "__jadpo_delivery_activations_v1" SET lease_until=$1,execution_deadline=$1 WHERE binding=$2',["not_an_instant",corrupt]);
let staged=false,finished=false,refused=false;
try {staged=await stage(old,[crypto.randomUUID()]);if(staged)finished=await finish(old);} catch {refused=true;}
if(staged||finished){violations.push("ACT-STORAGE-TIME-01");console.log(JSON.stringify({violation:"ACT-STORAGE-TIME-01",malformed_persisted_deadlines:"not_an_instant",staged,finished,refused}));}
else console.log('PASS malformed persisted deadlines fail closed');

if(sql) {
  const waitLock=async()=>{for(let i=0;i<400;i++){const a=await sql.unsafe("SELECT COUNT(*)::int AS n FROM pg_stat_activity WHERE datname=current_database() AND wait_event_type='Lock' AND query LIKE 'UPDATE%__jadpo_delivery_activations_v1%RETURNING%'");if(a[0].n>0)return;await Bun.sleep(10);}throw new Error("native activation row-lock wait not observed");};
  const waitExpired=async(lease:string)=>{for(let i=0;i<300;i++){const t=await sql.unsafe("SELECT to_char(clock_timestamp() AT TIME ZONE 'UTC','YYYY-MM-DD\"T\"HH24:MI:SS.MS\"Z\"') AS now");if(t[0].now>=lease)return;await Bun.sleep(10);}throw new Error("fixture DB lease did not expire within3s");};
  for(const op of ["claim","stage","finish"]) {
    const b=crypto.randomUUID();await tick(b);const handle=await claim(b,instant,{executionMs:2000,leaseMs:500});
    if(op==="finish") assert.equal(await stage(handle,["retained work"]),true);
    let ready!:()=>void,release!:()=>void;const entered=new Promise<void>(r=>ready=r),held=new Promise<void>(r=>release=r);
    const locker=sql.begin(async(tx:any)=>{await tx.unsafe('UPDATE "__jadpo_delivery_activations_v1" SET generation=generation WHERE binding=$1',[b]);ready();await held;});
    await entered;
    const reading=(op==="claim"?claim(b,resume):op==="stage"?stage(handle,["late work"]):finish(handle)).then(value=>({value,error:null}),error=>({value:null,error}));
    try{await waitLock();await waitExpired(handle.leaseUntil);}finally{release();await locker;}
    const result=await reading;assert.equal(result.error,null);
    if(op==="claim") {assert.equal(result.value.generation,"2");assert.equal(result.value.operationTime,resume);assert(result.value.leaseUntil>handle.leaseUntil);assert.equal(await stage(handle,[]),false);}
    else {assert.equal(result.value,false);assert.equal((await state(b)).activation_id,handle.activationId);if(op==="finish")assert.deepEqual(JSON.parse((await state(b)).page).intentIds,["retained work"]);else assert.equal((await state(b)).page,null);}
    console.log(JSON.stringify({late_lock_control:op,observed_lock:true,db_lease_expired:true,result:op==="claim"?"reclaimed_generation2":result.value}));
  }
}
if(sql)await sql.close();if(db)db.close();
console.log(JSON.stringify({adapter:sql?"postgres":"sqlite",complete:true,violations}));process.exit(violations.length?2:0);
